const ssoDomainVerifiedElsewhere = `-- name: SsoDomainVerifiedElsewhere :one
SELECT EXISTS (
    SELECT 1 FROM sso_domains d JOIN workspaces w ON w.id = d.workspace_id
    WHERE d.domain = $1 AND d.verified_at IS NOT NULL AND d.workspace_id <> $2 AND w.deleted_at IS NULL
) AS taken
`

type SsoDomainVerifiedElsewhereParams struct {
	Domain      string
	WorkspaceID uuid.UUID
}

func (q *Queries) SsoDomainVerifiedElsewhere(ctx context.Context, arg SsoDomainVerifiedElsewhereParams) (bool, error) {
	row := q.db.QueryRow(ctx, ssoDomainVerifiedElsewhere, arg.Domain, arg.WorkspaceID)
	var taken bool
	err := row.Scan(&taken)
	return taken, err
}

const ssoDomainVerifiedIn = `-- name: SsoDomainVerifiedIn :one
SELECT EXISTS (
    SELECT 1 FROM sso_domains WHERE workspace_id = $1 AND domain = $2 AND verified_at IS NOT NULL
) AS verified
`

type SsoDomainVerifiedInParams struct {
	WorkspaceID uuid.UUID
	Domain      string
}

func (q *Queries) SsoDomainVerifiedIn(ctx context.Context, arg SsoDomainVerifiedInParams) (bool, error) {
	row := q.db.QueryRow(ctx, ssoDomainVerifiedIn, arg.WorkspaceID, arg.Domain)
	var verified bool
	err := row.Scan(&verified)
	return verified, err
}

const ssoRequiredFor = `-- name: SsoRequiredFor :one
SELECT s.id, p.email FROM sso_settings s
JOIN people p ON p.id = $1
JOIN sso_domains d ON d.workspace_id = s.workspace_id AND d.verified_at IS NOT NULL
    AND d.domain = substring(p.email from '@([^@]*)$')
WHERE s.workspace_id = $2 AND s.sso_required AND s.protocol IS NOT NULL
LIMIT 1
`

type SsoRequiredForParams struct {
	PersonID    uuid.UUID
	WorkspaceID uuid.UUID
}

type SsoRequiredForRow struct {
	ID    uuid.UUID
	Email string
}

func (q *Queries) SsoRequiredFor(ctx context.Context, arg SsoRequiredForParams) (SsoRequiredForRow, error) {
	row := q.db.QueryRow(ctx, ssoRequiredFor, arg.PersonID, arg.WorkspaceID)
	var i SsoRequiredForRow
	err := row.Scan(&i.ID, &i.Email)
	return i, err
}

const takeSsoLogin = `-- name: TakeSsoLogin :one
DELETE FROM sso_logins WHERE state_hash = $1
RETURNING state_hash, workspace_id, settings_id, nonce, verifier, return_to, created_at, expires_at
`

// Found by the state's hash alone: the callback knows no workspace yet.
func (q *Queries) TakeSsoLogin(ctx context.Context, stateHash []byte) (SsoLogin, error) {
	row := q.db.QueryRow(ctx, takeSsoLogin, stateHash)
	var i SsoLogin
	err := row.Scan(
		&i.StateHash,
		&i.WorkspaceID,
		&i.SettingsID,
		&i.Nonce,
		&i.Verifier,
		&i.ReturnTo,
		&i.CreatedAt,
		&i.ExpiresAt,
	)
	return i, err
}
